+#[test]
+fn the_unmeasured_bore_band_rejects_the_old_mesh_readings() {
+    for got in [(4716, 4688, 549), (4726, 4698, 549), (3158, 3130, 1141)] {
+        assert!(!unmeasured_bore_path_matches(got), "the band must reject the old mesh reading {got:?}");
